import sysfrom PyQt5.QtWidgets import QApplicationfrom PyQt5.QtCore import QCommandLineParser, QCommandLineOptionfrom pymiri.gui import SelectData as sddef main():        app = QApplication(sys.argv)        parser = QCommandLineParser()    parser.setApplicationDescription("MIRI Data Selector")    parser.addHelpOption()    # 1. Create the Option objects correctly    # QCommandLineOption(names_list, description, valueName)    format_opt = QCommandLineOption(["f", "format"],                                     "File format",                                     "format",                                    "fits")    kind_opt = QCommandLineOption(["k", "kind"],                                   "Kind of data",                                   "kind",                                  "rate")    # 2. Add the objects to the parser    parser.addOption(format_opt)    parser.addOption(kind_opt)        # 3. Define positional argument (the filename/path)    parser.addPositionalArgument("file", "The input csv file")    parser.process(app)    # Extract values    file_format = parser.value("f")    data_kind = parser.value("k")        # Get positional arguments (returns a list)    pos_args = parser.positionalArguments()    input_file = pos_args[0] if pos_args else None        window = sd.MainWindow(input_file, file_format, data_kind)    window.show()    sys.exit(app.exec_())